    await expect(sdk.commands.vendorBills.setPaymentHold({ ...hold, idempotencyKey: "hold:stale" })).rejects.toMatchObject({ code: "optimistic_concurrency_conflict" });
    expect(await depositDatabaseState(pool)).toEqual(before);
