    expect(review.invoice).toMatchObject({documentDate:"2026-08-01",recognitionDate:"2026-08-12",dueDate:"2026-08-05",openAmount:"60.00"});
    expect(await depositDatabaseState(pool)).toEqual(beforeReview);
