async function documentBalances(pool: Pool): Promise<readonly Record<string, unknown>[]> {
  const result = await pool.query<{
    readonly subledger_document_id: string;
    readonly open_amount: string;
    readonly status: string;
    readonly version: number;
  }>(
    "select subledger_document_id, open_amount::text, status, version from erp_financials.subledger_documents where subledger_document_id in ('invoice_1', 'payment_1') order by subledger_document_id"
  );
  return result.rows;
}

async function creditOwnershipFixture(pool: Pool, customer: boolean) {
  await seedQuickBooksAllDocumentScope(pool);
  const base = quickBooksAllDocumentFacts();
  const types = customer ? ["credit_all", "invoice_all", "payment_all"] : ["vendor_credit_all", "bill_all", "bill_payment_all"];
  const ids = ["2572", "2573", "2574"];
  const resources: HandrailQuickBooksSdkResourceSet = {
    ...quickBooksAllDocumentResources(),
    operationalDocuments: types.map((type, index) => {
      const template = quickBooksAllDocumentResources().operationalDocuments?.find(row => row.resourceId === type);
      if (!template) throw new Error(`Missing fixture ${type}`);
      const id = ids[index];
      if (id === undefined) throw new Error("Missing fixture ID");
      const amount = index === 0 ? "1922.58" : index === 1 ? "1861.52" : "0.00";
      return { ...template, resourceId: id, resource: { ...template.resource,
        sourceTransactionId: id, transactionDate: index === 0 ? "2025-07-25" : "2025-08-19",
        dueDate: "2025-09-18", totalAmount: amount, openAmount: "0.00",
        ...(index === 2 ? { unappliedAmount: "0.00" } : {}),
        lines: index === 2 ? [0, 1].map(link => ({ sourceLineId: String(link + 1), lineNumber: link + 1,
          sourceAmount: "1861.52", linkedTransactions: [{ sourceTransactionId: link === 0 ? "2572" : "2573",
            sourceTransactionType: link === 0 ? (customer ? "CreditMemo" : "VendorCredit") : (customer ? "Invoice" : "Bill") }], postings: [] })) :
          [{ sourceLineId: "1", lineNumber: 1, sourceAmount: amount,
            accountRef: { sourceObjectId: customer ? "revenue" : "expense" }, postings: [] }]
      } };
    })
  };
  const facts: CanonicalAccountingFactSet = { ...base,
    transactions: types.slice(0, 2).map((type, index) => {
      const transaction = base.transactions.find(row => row.sourceTransactionId === type);
      if (!transaction) throw new Error(`Missing transaction ${type}`);
      return { ...transaction, sourceTransactionId: index === 0 ? "2572" : "2573" };
    }) };
  for (const transaction of facts.transactions) {
    await pool.query(`update erp_financials.transactions set source_transaction_id = $1 where transaction_id = $2`,
      [transaction.sourceTransactionId, transaction.transactionId]);
  }
  return { facts, resources };
}

async function creditOwnershipState(pool: Pool) {
  return {
    documents: await quickBooksDocumentState(pool),
    applications: (await pool.query<Record<string, unknown>>(`select subledger_application_id, applied_amount::text, status, version, applied_event_id, ended_event_id
      from erp_financials.subledger_applications order by subledger_application_id`)).rows,
    events: (await pool.query(`select * from erp_financials.financial_lifecycle_events order by event_id`)).rows,
    postings: (await pool.query(`select * from erp_financials.ledger_postings order by posting_id`)).rows
  };
}

function registerValue<T>(value: T | undefined): T {
  if (value === undefined) throw new Error("Missing expected account register fixture value");
  return value;
}

function requiredComponentFixture<T>(value:T|undefined):T { if(value===undefined)throw Error("Missing invoice component fixture");return value; }

/** Historical fixture construction only: emit the pre-schema43 SQL shape.
 * No query results or accounting facts are mocked; every statement reaches PG.
 * This is not a runtime compatibility adapter or proof of an old SDK binary.
 * The adapter refuses explicit components because those did not exist then. */
function preComponentFixtureRunner(database:ErpFinancialsTransactionRunner):ErpFinancialsTransactionRunner {
  return {transaction:work=>preCrossSourceFixtureRunner(database).transaction(client=>work({
    query<Row extends Record<string,unknown>>(sql:string,params:readonly unknown[]=[]):Promise<PostgresQueryResult<Row>> {
      if(sql.includes('insert into "erp_financials"."subledger_document_lines"')){
        if(params.length!==22||params[20]!==undefined||params[21]!==undefined)throw Error("Historical fixture cannot contain component accounts");
        return client.query<Row>(sql.replace(', "tax_account_id", "discount_account_id"','').replace(', $21, $22',''),params.slice(0,20));
      }
      // Pre-component cancellation inferred its sole AR debit. Optional line
      // reads likewise had no component columns; NULL retains that old shape.
      const historicalSql=sql.replace(/(?:(?:"?[a-z_]+"?)\.)?"?(?:tax_account_id|discount_account_id)"?/gu,'null::text');
      return client.query<Row>(historicalSql,params);
    }
  }))};
}
/** Historical fixture construction only; retain pre-schema50 same-source SQL.
 * Reject cross-source coordinates, and execute all actual accounting in PG. */
function preCrossSourceFixtureRunner(database:ErpFinancialsTransactionRunner):ErpFinancialsTransactionRunner {
  return {transaction:work=>database.transaction(client=>work({
    query<Row extends Record<string,unknown>>(sql:string,params:readonly unknown[]=[]):Promise<PostgresQueryResult<Row>> {
      if(sql.includes('insert into "erp_financials"."subledger_applications"') && sql.includes('"target_document_source_id"')){
        if(params.length!==19||params[18]!==null)throw Error("Historical fixture cannot contain cross-source applications");
        return client.query<Row>(sql.replace(', "target_document_source_id"','').replace(', $19)',')'),params.slice(0,18));
      }
      return client.query<Row>(sql.replace(/(?:(?:"?[a-z_]+"?)\.)?"?target_document_source_id"?/gu,'null::text'),params);
    }
  }))};
}
function stripNewCrossSourceNulls(state:Record<string,unknown[]>):Record<string,unknown[]> {
  const result=structuredClone(state);
  for(const entry of result.subledger_applications??[]){
    const row=(entry as {row:Record<string,unknown>}).row;
    expect(row.target_document_source_id).toBeNull();delete row.target_document_source_id;
  }
  return result;
}
function stripNewRecognitionNulls(state:Record<string,unknown[]>):Record<string,unknown[]> {
  const result=stripNewCrossSourceNulls(state);
  for(const entry of result.subledger_documents??[]){
    const row=(entry as {row:Record<string,unknown>}).row;
    expect(row.recognition_date).toBeNull();delete row.recognition_date;
  }
  return result;
}
function stripNewComponentNulls(state:Record<string,unknown[]>):Record<string,unknown[]> {
  const result=stripNewRecognitionNulls(state);
  for(const table of ["invoice_draft_lines","subledger_document_lines"])for(const entry of result[table]??[]){
    const row=(entry as {row:Record<string,unknown>}).row;
    expect(row.tax_account_id).toBeNull();expect(row.discount_account_id).toBeNull();
    delete row.tax_account_id;delete row.discount_account_id;
  }
  return result;
}

/** Check schema-49 initial control rows separately from preserved accounting history. */
function expectInitialMaintenanceTables(before: Record<string, unknown[]>, after: Record<string, unknown[]>): void {
  expect(before.accounting_access_control).toBeUndefined();
  expect(before.accounting_access_commands).toBeUndefined();
  expect(after.accounting_access_control).toEqual([{ row: { control_id: "database", revision: 0, active_session_id: null } }]);
  expect(after.accounting_access_commands).toEqual([]);
  before.accounting_access_control = [{ row: { control_id: "database", revision: 0, active_session_id: null } }];
  before.accounting_access_commands = [];
}
